1	/**
2	 * Calendar helpers. Dates travel through the library as ISO strings
3	 * ("YYYY-MM-DD") with no time or zone attached; day arithmetic happens on UTC
4	 * day numbers so that daylight saving can never shift a result.
5	 */
6	
7	const ISO_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;
8	const MS_PER_DAY = 86_400_000;
9	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
10	
11	export function isLeapYear(year) {
12	  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
13	}
14	
15	/** Days in a month, where month is 1 to 12. */
16	export function daysInMonth(year, month) {
17	  if (month === 2) return isLeapYear(year) ? 29 : 28;
18	  return [4, 6, 9, 11].includes(month) ? 30 : 31;
19	}
20	
21	function pad(value, width) {
22	  return String(value).padStart(width, '0');
23	}
24	
25	/** Splits an ISO date into numbers, rejecting impossible dates. */
26	export function parseIsoDate(text) {
27	  const match = ISO_DATE.exec(String(text));
28	  if (!match) throw new RangeError(`Not an ISO date: ${text}`);
29	  const [year, month, day] = match.slice(1).map(Number);
30	  if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
31	    throw new RangeError(`Not a calendar date: ${text}`);
32	  }
33	  return { year, month, day };
34	}
35	
36	export function formatIsoDate({ year, month, day }) {
37	  return `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
38	}
39	
40	function toDayNumber(text) {
41	  const { year, month, day } = parseIsoDate(text);
42	  return Date.UTC(year, month - 1, day) / MS_PER_DAY;
43	}
44	
45	function fromDayNumber(dayNumber) {
46	  const date = new Date(dayNumber * MS_PER_DAY);
47	  return formatIsoDate({
48	    year: date.getUTCFullYear(),
49	    month: date.getUTCMonth() + 1,
50	    day: date.getUTCDate(),
51	  });
52	}
53	
54	/** Whole days from `from` to `to`; negative when `to` is earlier. */
55	export function daysBetween(from, to) {
56	  return toDayNumber(to) - toDayNumber(from);
57	}
58	
59	export function addDays(text, days) {
60	  return fromDayNumber(toDayNumber(text) + days);
61	}
62	
63	/** Negative, zero or positive, like a sort comparator. */
64	export function compareDates(a, b) {
65	  return toDayNumber(a) - toDayNumber(b);
66	}
67	
68	export function isLastDayOfMonth(text) {
69	  const { year, month, day } = parseIsoDate(text);
70	  return day === daysInMonth(year, month);
71	}
72	
73	/**
74	 * Moves a date by whole calendar months. If the target month is too short the
75	 * result lands on its last day: addMonths("2023-01-31", 1) is "2023-02-28".
76	 */
77	export function addMonths(text, months) {
78	  const { year, month, day } = parseIsoDate(text);
79	  const monthIndex = year * 12 + (month - 1) + months;
80	  const targetYear = Math.floor(monthIndex / 12);
81	  const targetMonth = monthIndex - targetYear * 12 + 1;
82	  return formatIsoDate({
83	    year: targetYear,
84	    month: targetMonth,
85	    day: Math.min(day, daysInMonth(targetYear, targetMonth)),
86	  });
87	}
88	
89	/** The calendar month of a date, as "YYYY-MM". */
90	export function monthKey(text) {
91	  return String(text).slice(0, 7);
92	}
93	
94	/** The first day of the month after the given date. */
95	export function firstOfNextMonth(text) {
96	  const { year, month } = parseIsoDate(text);
97	  const next = addMonths(formatIsoDate({ year, month, day: 1 }), 1);
98	  return next;
99	}
100	
101	/** "2024-02-29" becomes "29 Feb 2024", for statements. */
102	export function formatLongDate(text) {
103	  const { year, month, day } = parseIsoDate(text);
104	  return `${day} ${MONTHS[month - 1]} ${year}`;
105	}
