34	/** A request that breaks a billing rule, such as crediting more than is left. */
35	export class BillingRuleError extends RangeError {
36	  constructor(message, details = {}) {
37	    super(message);
38	    this.name = 'BillingRuleError';
39	    this.details = details;
40	  }
41	}
42	
43	/** A reference to a subscription, invoice or plan that does not exist. */
44	export class UnknownRecordError extends RangeError {
45	  constructor(kind, key) {
46	    super(`Unknown ${kind}: ${key}`);
47	    this.name = 'UnknownRecordError';
48	    this.kind = kind;
