1	/**
2	 * Billing periods. A subscription renews every `intervalMonths` months from
3	 * its anchor date. A period runs from its start up to, but not including, its
4	 * end, and each period starts where the previous one ended.
5	 */
6	
7	import {
8	  compareDates,
9	  daysBetween,
10	  firstOfNextMonth,
11	  formatIsoDate,
12	  monthKey,
13	  parseIsoDate,
14	} from '../core/dates.mjs';
15	
16	const MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
17	
18	function assertInterval(intervalMonths) {
19	  if (!Number.isInteger(intervalMonths) || intervalMonths < 1) {
20	    throw new RangeError(`intervalMonths must be a positive integer, got ${intervalMonths}`);
21	  }
22	}
23	
24	/** The renewal date after `date`, keeping its day where the month allows. */
25	function nextBoundary(date, intervalMonths) {
26	  const { year, month, day } = parseIsoDate(date);
27	  const monthIndex = year * 12 + (month - 1) + intervalMonths;
28	  const nextYear = Math.floor(monthIndex / 12);
29	  const nextMonth = monthIndex - nextYear * 12;
30	  return formatIsoDate({
31	    year: nextYear,
32	    month: nextMonth + 1,
33	    day: Math.min(day, MONTH_LENGTHS[nextMonth]),
34	  });
35	}
36	
37	/** The period that follows the given one. */
38	export function periodAfter(period, intervalMonths) {
39	  return {
40	    index: period.index + 1,
41	    start: period.end,
42	    end: nextBoundary(period.end, intervalMonths),
43	  };
44	}
45	
46	/** The period at a zero-based index. */
47	export function periodAt(anchor, intervalMonths, index) {
48	  assertInterval(intervalMonths);
49	  if (!Number.isInteger(index) || index < 0) {
50	    throw new RangeError(`index must be a non-negative integer, got ${index}`);
51	  }
52	  parseIsoDate(anchor);
53	  let period = { index: 0, start: anchor, end: nextBoundary(anchor, intervalMonths) };
54	  while (period.index < index) period = periodAfter(period, intervalMonths);
55	  return period;
56	}
57	
58	/** The first `count` billing periods from the anchor. */
59	export function billingPeriods(anchor, intervalMonths, count) {
60	  assertInterval(intervalMonths);
61	  parseIsoDate(anchor);
62	  const periods = [];
63	  for (let index = 0; index < count; index += 1) {
64	    periods.push(periodAt(anchor, intervalMonths, index));
65	  }
66	  return periods;
67	}
68	
69	/** The period a date falls in. Dates before the anchor have no period. */
70	export function periodContaining(anchor, intervalMonths, date) {
71	  assertInterval(intervalMonths);
72	  if (compareDates(date, anchor) < 0) {
73	    throw new RangeError(`${date} is before the subscription anchor ${anchor}`);
74	  }
75	  let period = periodAt(anchor, intervalMonths, 0);
76	  while (compareDates(date, period.end) >= 0) period = periodAfter(period, intervalMonths);
77	  return period;
78	}
79	
80	/** The first `count` renewal dates strictly after `date`. */
81	export function renewalsAfter(anchor, intervalMonths, date, count) {
82	  const renewals = [];
83	  let period = periodContaining(anchor, intervalMonths, date);
84	  while (renewals.length < count) {
85	    renewals.push(period.end);
86	    period = periodAfter(period, intervalMonths);
87	  }
88	  return renewals;
89	}
90	
91	/**
92	 * The days a period spends in each calendar month, in order:
93	 * [{ month: '2024-01', days: 17 }, { month: '2024-02', days: 14 }]
94	 */
95	export function daysByMonth(period) {
96	  const months = [];
97	  let cursor = period.start;
98	  while (compareDates(cursor, period.end) < 0) {
99	    const nextMonth = firstOfNextMonth(cursor);
100	    const stop = compareDates(nextMonth, period.end) < 0 ? nextMonth : period.end;
101	    months.push({ month: monthKey(cursor), days: daysBetween(cursor, stop) });
102	    cursor = stop;
103	  }
104	  return months;
105	}
106	
107	/** True when `date` is on or after the period's start and before its end. */
108	export function isWithinPeriod(period, date) {
109	  return compareDates(date, period.start) >= 0 && compareDates(date, period.end) < 0;
110	}
