66	/** The record once the change's invoice has gone out. */
67	export function applyPlanChange(record, change, invoice) {
68	  const { plan, seats } = resolveTerms(record, change);
69	  const index = chargeLineIndex(invoice);
70	  const changes = {
71	    couponUses: nextCouponUses(record),
72	    plan,
73	    seats,
74	    segment: segmentFor(invoice, index, change.date, record.period.end),
75	  };
76	  // The new terms go through the same checks as a new subscription.
77	  return createRecord({ ...record, ...changes });
78	}
