80	/**
81	 * The invoice input that gives back the unused time, or null when there is
82	 * nothing to give back.
83	 */
84	export function draftCancellation(record, date, context) {
85	  const { number, taxRateBps, reversedNet } = context;
86	  const credit = unusedCredit(record, date, reversedNet);
87	  if (credit === 0) return null;
88	  return {
89	    number,
90	    customerId: record.customerId,
91	    subscriptionId: record.id,
92	    currency: record.currency,
93	    issueDate: date,
94	    lines: [
95	      {
96	        description: `Unused ${record.plan.name} (${date} to ${record.period.end})`,
97	        unitAmount: -credit,
98	        taxRateBps,
99	        period: { start: date, end: record.period.end },
100	        reverses: reversalLink(record.segment),
101	      },
102	    ],
103	  };
104	}
