1	/**
2	 * Credit notes reverse part or all of an invoice's lines. An invoice can have
3	 * any number of them, so each new note is issued against the ones before it.
4	 *
5	 * Credit lines on later invoices can also give back part of an earlier charge.
6	 * Those are read here in the same shape as credit note lines.
7	 */
8	
9	import { compareDates, parseIsoDate } from '../core/dates.mjs';
10	import { assertMinorUnits, parseAmount, sumAmounts } from '../core/money.mjs';
11	import { assertNonEmptyArray, assertText } from '../core/validate.mjs';
12	import { taxForAmount } from '../tax/calculate.mjs';
13	
14	/** One entry per earlier invoice a new invoice gives money back on. */
15	export function reversalsFromInvoice(invoice) {
16	  const byOrigin = new Map();
17	  for (const line of invoice.lines) {
18	    if (!line.reverses) continue;
19	    const { invoiceNumber, lineIndex } = line.reverses;
20	    if (!byOrigin.has(invoiceNumber)) byOrigin.set(invoiceNumber, []);
21	    byOrigin.get(invoiceNumber).push({ lineIndex, net: -line.net, tax: -line.tax });
22	  }
23	  return [...byOrigin].map(([invoiceNumber, lines]) => ({
24	    kind: 'reversal',
25	    number: invoice.number,
26	    invoiceNumber,
27	    currency: invoice.currency,
28	    date: invoice.issueDate,
29	    lines,
30	  }));
31	}
32	
33	function assertNotesBelongTo(invoice, notes) {
34	  for (const note of notes) {
35	    if (note.invoiceNumber !== invoice.number) {
36	      throw new RangeError(`Credit note ${note.number} belongs to invoice ${note.invoiceNumber}`);
37	    }
38	  }
39	}
40	
41	/** Per invoice line, the net and tax already given back. */
42	export function creditedToDate(invoice, notes = []) {
43	  assertNotesBelongTo(invoice, notes);
44	  const credited = invoice.lines.map(() => ({ net: 0, tax: 0 }));
45	  for (const note of notes) {
46	    for (const line of note.lines) {
47	      credited[line.lineIndex].net += line.net;
48	      credited[line.lineIndex].tax += line.tax;
49	    }
50	  }
51	  return credited;
52	}
53	
54	/** Per invoice line, the net amount that can still be credited. */
55	export function remainingCreditable(invoice, notes = []) {
56	  const credited = creditedToDate(invoice, notes);
57	  return invoice.lines.map((line, index) => Math.max(line.amount - credited[index].net, 0));
58	}
59	
60	function requestedAmount(invoice, request, available) {
61	  if (request.amount !== undefined) {
62	    assertMinorUnits(request.amount, 'credit amount');
63	    return request.amount;
64	  }
65	  if (request.amountText !== undefined) return parseAmount(request.amountText, invoice.currency);
66	  return available;
67	}
68	
69	function creditLine(invoice, entry, credited) {
70	  const line = invoice.lines[entry.lineIndex];
71	  if (!line) throw new RangeError(`Invoice ${invoice.number} has no line ${entry.lineIndex}`);
72	  if (line.net <= 0) {
73	    throw new RangeError(`Line ${entry.lineIndex} of ${invoice.number} has nothing to credit`);
74	  }
75	
76	  const soFar = credited[entry.lineIndex];
77	  const available = Math.max(line.amount - soFar.net, 0);
78	  const amount = requestedAmount(invoice, entry, available);
79	  if (amount <= 0 || amount > line.amount) {
80	    throw new RangeError(`Cannot credit ${amount} on line ${entry.lineIndex} of ${invoice.number}`);
81	  }
82	
83	  const tax = taxForAmount(amount, line.taxRateBps);
84	  credited[entry.lineIndex] = { net: soFar.net + amount, tax: soFar.tax + tax };
85	  return {
86	    lineIndex: entry.lineIndex,
87	    description: line.description,
88	    taxRateBps: line.taxRateBps,
89	    net: amount,
90	    tax,
91	    gross: amount + tax,
92	  };
93	}
94	
95	/**
96	 * Issues a credit note. `request.lines` holds { lineIndex, amount } entries;
97	 * amount is a net amount in minor units, or decimal text as amountText. With
98	 * neither, the entry credits everything left on that line.
99	 */
100	export function issueCreditNote(invoice, request, priorNotes = []) {
101	  const { number, date, reason = '', lines } = request;
102	  assertText(number, 'Credit note number');
103	  parseIsoDate(date);
104	  if (compareDates(date, invoice.issueDate) < 0) {
105	    throw new RangeError(`Credit note ${number} predates invoice ${invoice.number}`);
106	  }
107	  assertNonEmptyArray(lines, 'Credit note lines');
108	
109	  const credited = creditedToDate(invoice, priorNotes);
110	  const noteLines = lines.map((entry) => creditLine(invoice, entry, credited));
111	
112	  const netTotal = sumAmounts(noteLines.map((line) => line.net));
113	  const taxTotal = sumAmounts(noteLines.map((line) => line.tax));
114	  return {
115	    number,
116	    invoiceNumber: invoice.number,
117	    customerId: invoice.customerId,
118	    currency: invoice.currency,
119	    date,
120	    reason,
121	    lines: noteLines,
122	    netTotal,
123	    taxTotal,
124	    total: netTotal + taxTotal,
125	  };
126	}
127	
128	/** Credits everything still creditable on an invoice's positive lines. */
129	export function creditInvoiceInFull(invoice, request, priorNotes = []) {
130	  const available = remainingCreditable(invoice, priorNotes);
131	  const lines = invoice.lines
132	    .map((line, lineIndex) => ({ line, lineIndex }))
133	    .filter(({ line, lineIndex }) => line.net > 0 && available[lineIndex] > 0)
134	    .map(({ lineIndex }) => ({ lineIndex }));
135	  return issueCreditNote(invoice, { ...request, lines }, priorNotes);
136	}
