1	/**
2	 * Double-entry journal for the accounting system. Every document becomes one
3	 * entry, and each leg is signed: positive is a debit, negative a credit. An entry
4	 * whose legs do not sum to zero is rejected by the accounting system on import.
5	 */
6	
7	import { sumAmounts } from '../core/money.mjs';
8	
9	export const ACCOUNTS = Object.freeze({
10	  receivables: '1100 Receivables',
11	  cash: '1000 Cash',
12	  customerCredit: '2100 Customer credit',
13	  taxPayable: '2200 Tax payable',
14	  revenue: '4000 Revenue',
15	  badDebt: '6900 Bad debt',
16	});
17	
18	function leg(account, amount) {
19	  return { account, amount };
20	}
21	
22	function entry(date, reference, currency, legs) {
23	  return {
24	    date,
25	    reference,
26	    currency,
27	    legs: legs.filter(({ amount }) => amount !== 0),
28	  };
29	}
30	
31	/** The entry for an invoice. */
32	export function invoiceEntry(invoice) {
33	  const toAccount = Math.max(-invoice.total, 0);
34	  return entry(invoice.issueDate, invoice.number, invoice.currency, [
35	    leg(ACCOUNTS.receivables, invoice.amountDue),
36	    leg(ACCOUNTS.customerCredit, invoice.creditApplied - toAccount),
37	    leg(ACCOUNTS.revenue, -invoice.netTotal),
38	    leg(ACCOUNTS.taxPayable, -invoice.taxTotal),
39	  ]);
40	}
41	
42	/** The entry for a credit note, following where its money went. */
43	export function creditNoteEntry(note) {
44	  const settlement = note.settlement ?? { againstBalance: note.total, refunded: 0, toAccount: 0 };
45	  return entry(note.date, note.number, note.currency, [
46	    leg(ACCOUNTS.revenue, note.netTotal),
47	    leg(ACCOUNTS.taxPayable, note.taxTotal),
48	    leg(ACCOUNTS.receivables, -settlement.againstBalance),
49	    leg(ACCOUNTS.cash, -settlement.refunded),
50	    leg(ACCOUNTS.customerCredit, -settlement.toAccount),
51	  ]);
52	}
53	
54	/** The entry for a payment or a write-off. */
55	export function settlementEntry(settlement) {
56	  const offset = settlement.kind === 'payment' ? ACCOUNTS.cash : ACCOUNTS.badDebt;
57	  return entry(settlement.date, settlement.invoiceNumber, settlement.currency, [
58	    leg(offset, settlement.amount),
59	    leg(ACCOUNTS.receivables, -settlement.amount),
60	  ]);
61	}
62	
63	export function entryImbalance(journalEntry) {
64	  return sumAmounts(journalEntry.legs.map(({ amount }) => amount));
65	}
66	
67	/** All entries for a set of documents, in date order. */
68	export function buildJournal({ invoices, notes, settlements }) {
69	  const entries = [
70	    ...invoices.map(invoiceEntry),
71	    ...notes.map(creditNoteEntry),
72	    ...settlements.map(settlementEntry),
73	  ];
74	  return entries.sort((a, b) => a.date.localeCompare(b.date) || a.reference.localeCompare(b.reference));
75	}
76	
77	/** Per account and currency, the balance the journal leaves. */
78	export function trialBalance(entries) {
79	  const balances = new Map();
80	  for (const { currency, legs } of entries) {
81	    for (const { account, amount } of legs) {
82	      const key = `${currency} ${account}`;
83	      balances.set(key, (balances.get(key) ?? 0) + amount);
84	    }
85	  }
86	  return Object.fromEntries([...balances].sort(([a], [b]) => a.localeCompare(b)));
87	}
