134	  /**
135	   * Moves a subscription into its next period. Returns the renewal invoice, or
136	   * null if the subscription was set to end instead.
137	   */
138	  function renew(id, options = {}) {
139	    const record = requireSubscription(id);
140	    if (record.status !== 'active') throw new RangeError(`Subscription ${id} has ended`);
141	    const period = nextPeriod(record);
142	    if (isCancelling(record)) {
143	      subscriptions.set(id, endRecord(record, period.start));
144	      timeline.record(id, 'ended', period.start);
145	      return null;
146	    }
147	    const terms = applyScheduled(record);
148	    const invoice = issue(
149	      draftPeriodInvoice(terms, period, {
150	        number: invoiceNumbers.take(),
151	        taxRateBps: taxRate(terms, period.start),
152	        discount: options.discount,
153	      }),
154	    );
155	    subscriptions.set(id, enterPeriod(terms, period, invoice));
156	    timeline.record(id, 'renewed', period.start, { invoiceNumber: invoice.number });
157	    return invoice;
158	  }
159	
160	  function resolveChange(request) {
161	    const { date, planCode, seats } = request;
162	    return { date, seats, plan: planCode ? catalog.plan(planCode) : undefined };
163	  }
164	
165	  /** Changes plan or seats today. Returns the invoice for the change. */
166	  function changePlan(id, request) {
167	    const record = requireSubscription(id);
168	    const change = resolveChange(request);
169	    const invoice = issue(
170	      draftPlanChange(record, change, {
171	        number: invoiceNumbers.take(),
172	        taxRateBps: taxRate(record, change.date),
173	        reversedNet: reversedNetOnSegment(record.segment),
174	      }),
175	    );
176	    subscriptions.set(id, applyPlanChange(record, change, invoice));
177	    timeline.record(id, 'changed', change.date, { invoiceNumber: invoice.number });
178	    return invoice;
179	  }
180	
181	  /** What a change would come to, without doing it. */
182	  function previewChange(id, request) {
183	    const record = requireSubscription(id);
184	    const change = resolveChange(request);
185	    return buildInvoice({
186	      ...draftPlanChange(record, change, {
187	        number: 'PREVIEW',
188	        taxRateBps: taxRate(record, change.date),
189	        reversedNet: reversedNetOnSegment(record.segment),
190	      }),
191	      accountCredit: account.balance(record.customerId, record.currency),
192	    });
193	  }
194	
195	  /** Sets new terms to take effect at the next renewal. */
196	  function scheduleForRenewal(id, request) {
197	    const record = requireSubscription(id);
198	    const { planCode, seats } = request;
199	    const plan = planCode ? catalog.plan(planCode) : undefined;
200	    subscriptions.set(id, scheduleChange(record, { plan, seats }));
201	    timeline.record(id, 'change-scheduled', record.period.start);
202	  }
203	
204	  function clearSchedule(id) {
205	    const record = requireSubscription(id);
206	    subscriptions.set(id, clearScheduled(record));
207	    timeline.record(id, 'schedule-cleared', record.period.start);
208	  }
209	
210	  /**
211	   * Cancels a subscription, either straight away (mode 'immediate'), giving back
212	   * the unused time, or when the current period ends (mode 'period-end').
213	   * Returns the invoice for the unused time, if there is one.
214	   */
215	  function cancel(id, { date, mode = 'immediate' }) {
216	    const record = requireSubscription(id);
217	    if (record.status !== 'active') throw new RangeError(`Subscription ${id} has ended`);
218	    if (mode === 'period-end') {
219	      subscriptions.set(id, scheduleChange(record, { cancel: true }));
220	      timeline.record(id, 'cancelled', date);
221	      return null;
222	    }
223	    if (mode !== 'immediate') throw new RangeError(`Unknown cancellation mode: ${mode}`);
224	
225	    const input = draftCancellation(record, date, {
226	      number: invoiceNumbers.peek(),
227	      taxRateBps: taxRate(record, date),
228	      reversedNet: reversedNetOnSegment(record.segment),
229	    });
230	    const invoice = input ? issue({ ...input, number: invoiceNumbers.take() }) : null;
231	    subscriptions.set(id, endRecord(record, date));
232	    timeline.record(id, 'cancelled', date, invoice ? { invoiceNumber: invoice.number } : {});
233	    return invoice;
234	  }
235	
236	  /**
237	   * Issues a credit note. Pass `lines` to credit part of an invoice, or leave it
238	   * out to credit everything still creditable.
239	   */
240	  function creditInvoice(number, request) {
241	    const invoice = requireInvoice(number);
242	    const { date, reason, lines } = request;
243	    const prior = drawnAgainst(number);
244	    const noteRequest = { number: noteNumbers.peek(), date, reason, lines };
245	    const draft = lines
246	      ? issueCreditNote(invoice, noteRequest, prior)
247	      : creditInvoiceInFull(invoice, noteRequest, prior);
248	    noteNumbers.take();
249	
250	    const settlement = settleCreditNote(draft.total, {
251	      openBalance: balanceOf(invoice),
252	    });
253	    const note = { ...draft, settlement };
254	    notes.push(note);
255	    if (settlement.toAccount > 0) {
256	      account.add(invoice.customerId, invoice.currency, settlement.toAccount, {
257	        date,
258	        reference: note.number,
259	      });
260	    }
261	    return note;
262	  }
263	
264	  /** Puts goodwill credit on a customer's account. */
265	  function grantAccountCredit(customerId, currency, { amount, date, reason = 'goodwill' }) {
266	    account.add(customerId, currency, amount, { date, reference: reason });
267	  }
268	
269	  function settle(number, kind, { amount, date }) {
270	    const invoice = requireInvoice(number);
271	    const settlement = createSettlement(invoice, kind, amount, date);
272	    if (compareDates(date, invoice.issueDate) < 0) {
273	      throw new RangeError(`${kind} on ${number} predates the invoice`);
274	    }
275	    if (amount > balanceOf(invoice)) {
276	      throw new RangeError(`${number} has less than ${amount} open`);
277	    }
278	    settlements.push(settlement);
279	    return settlement;
280	  }
281	
282	  /**
283	   * Renews every active subscription whose current period has ended by `asOf`,
284	   * as many times as it takes to catch up. Returns the invoices in order.
285	   */
286	  function runRenewals(asOf) {
287	    const issued = [];
288	    for (const id of subscriptions.keys()) {
289	      let record = subscriptions.get(id);
290	      while (record.status === 'active' && compareDates(record.period.end, asOf) <= 0) {
291	        const invoice = renew(id);
292	        if (invoice) issued.push(invoice);
293	        record = subscriptions.get(id);
294	      }
295	    }
296	    return issued;
297	  }
298	
299	  function allInvoices() {
300	    return [...invoices.values()];
301	  }
302	
303	  function journal() {
304	    return buildJournal({ invoices: allInvoices(), notes, settlements });
305	  }
306	
307	  return {
308	    customers,
309	    subscribe,
310	    renew,
311	    runRenewals,
312	    changePlan,
313	    previewChange,
314	    scheduleForRenewal,
315	    clearSchedule,
316	    cancel,
317	    creditInvoice,
318	    grantAccountCredit,
319	    pay: (number, payment) => settle(number, 'payment', payment),
320	    writeOff: (number, entry) => settle(number, 'write-off', entry),
321	
322	    subscription: requireSubscription,
323	    invoice: requireInvoice,
324	    invoices: allInvoices,
325	    notes: () => [...notes],
326	    notesOn,
327	    settlementsOn,
328	    balanceOf: (number) => balanceOf(requireInvoice(number)),
329	    remainingCreditable: (number) => remainingCreditable(requireInvoice(number), drawnAgainst(number)),
330	    accountCredit: (customerId, currency) => account.balance(customerId, currency),
331	    timeline: (id) => describeEvents(timeline.of(id)),
332	
333	    statement(number) {
334	      return renderStatement(requireInvoice(number), notesOn(number), settlementsOn(number));
335	    },
336	    accountStatement(customerId, currency) {
337	      return renderAccountStatement(customerId, currency, account.entries(customerId, currency));
338	    },
339	    revenueByMonth: (currency) => revenueByMonth({ invoices: allInvoices(), notes, currency }),
340	    taxReport: (currency, month) => taxReport({ invoices: allInvoices(), notes, currency, month }),
341	    aging(currency, asOf, termsDays) {
342	      return agingReport({ invoices: allInvoices(), balanceOf, asOf, currency, termsDays });
343	    },
344	    dunning: (asOf, termsDays) => dunningQueue(allInvoices(), balanceOf, asOf, termsDays),
345	    customerSummary(customerId, currency) {
346	      return customerSummary({
347	        customerId,
348	        currency,
349	        invoices: allInvoices(),
350	        notes,
351	        settlements,
352	        account,
353	        balanceOf,
354	      });
355	    },
356	    monthlyRecurringRevenue: (currency) =>
357	      monthlyRecurringRevenue([...subscriptions.values()], currency),
358	    renewalForecast: (currency) => renewalForecast([...subscriptions.values()], currency),
359	    subscriberMovement: (month) => subscriberMovement([...subscriptions.values()], month),
360	    churn: (month) => monthlyChurnBps([...subscriptions.values()], month),
361	    subscribersByPlan: () => subscribersByPlan([...subscriptions.values()]),
362	    deferredRevenue: (currency, asOf) => deferredRevenue({ invoices: allInvoices(), currency, asOf }),
363	    revenueCsv: (currency) =>
364	      revenueCsv(revenueByMonth({ invoices: allInvoices(), notes, currency }), currency),
365	    journalCsv: () => journalCsv(journal()),
366	    refundsToPay: () => refundQueue(notes, refundsPaidOut),
367	    markRefundPaid(noteNumber) {
368	      refundsPaidOut.push(noteNumber);
369	    },
370	    journal,
371	    unbalancedJournalEntries: () => journal().filter((entry) => entryImbalance(entry) !== 0),
372	    trialBalance: () => trialBalance(journal()),
373	    snapshot: (takenOn) =>
374	      bookSnapshot({
375	        subscriptions: [...subscriptions.values()],
376	        invoices: allInvoices(),
377	        notes,
378	        settlements,
379	        takenOn,
380	      }),
381	    invoicesCsv: () => invoicesCsv(allInvoices()),
382	    creditNotesCsv: () => creditNotesCsv(notes),
383	  };
384	}
