1	/**
2	 * Plain-text statements: the view of an invoice and its credit notes that goes
3	 * out to customers.
4	 */
5	
6	import { formatLongDate } from '../core/dates.mjs';
7	import { formatAmount } from '../core/money.mjs';
8	import { invoiceBalance } from '../ledger/balances.mjs';
9	
10	const DESCRIPTION_WIDTH = 44;
11	const NUMBER_WIDTH = 12;
12	
13	function row(description, ...numbers) {
14	  const cells = numbers.map((value) => String(value).padStart(NUMBER_WIDTH));
15	  return [String(description).padEnd(DESCRIPTION_WIDTH), ...cells].join(' ').trimEnd();
16	}
17	
18	function cell(minor) {
19	  return (minor / 100).toFixed(2);
20	}
21	
22	function ratePercent(rateBps) {
23	  const percent = rateBps / 100;
24	  return `${Number.isInteger(percent) ? percent : percent.toFixed(2)}%`;
25	}
26	
27	function invoiceLines(invoice) {
28	  const header = row('Description', 'Amount', 'Discount', 'Net', 'Tax', 'Gross');
29	  const body = invoice.lines.map((line) =>
30	    row(
31	      line.description,
32	      cell(line.amount),
33	      cell(line.discount),
34	      cell(line.net),
35	      cell(line.tax),
36	      cell(line.gross),
37	    ),
38	  );
39	  return [header, ...body];
40	}
41	
42	function creditNoteLines(invoice, notes) {
43	  const out = [];
44	  for (const note of notes) {
45	    out.push('', `Credit note ${note.number} on ${formatLongDate(note.date)}`);
46	    if (note.reason) out.push(`Reason: ${note.reason}`);
47	    for (const line of note.lines) {
48	      out.push(row(line.description, '', '', cell(-line.net), cell(-line.tax), cell(-line.gross)));
49	    }
50	    out.push(`Credited: ${formatAmount(-note.total, invoice.currency)}`);
51	  }
52	  return out;
53	}
54	
55	function settlementLines(invoice, settlements) {
56	  return settlements.map((settlement) => {
57	    const label = settlement.kind === 'payment' ? 'Payment' : 'Written off';
58	    const when = formatLongDate(settlement.date);
59	    return `${label} on ${when}: ${formatAmount(-settlement.amount, invoice.currency)}`;
60	  });
61	}
62	
63	export function renderStatement(invoice, notes = [], settlements = []) {
64	  const { currency } = invoice;
65	  const out = [
66	    `Invoice ${invoice.number}`,
67	    `Customer ${invoice.customerId}`,
68	    `Issued ${formatLongDate(invoice.issueDate)}`,
69	    `Currency ${currency}`,
70	    '',
71	    ...invoiceLines(invoice),
72	    '',
73	    `Subtotal: ${formatAmount(invoice.subtotal, currency)}`,
74	    `Discount: ${formatAmount(-invoice.discountTotal, currency)}`,
75	    `Net: ${formatAmount(invoice.netTotal, currency)}`,
76	  ];
77	  for (const { rateBps, taxable, tax } of invoice.taxSummary) {
78	    const base = formatAmount(taxable, currency);
79	    out.push(`Tax at ${ratePercent(rateBps)} on ${base}: ${formatAmount(tax, currency)}`);
80	  }
81	  out.push(`Total: ${formatAmount(invoice.total, currency)}`);
82	  if (invoice.creditApplied > 0) {
83	    out.push(`Account credit used: ${formatAmount(-invoice.creditApplied, currency)}`);
84	  }
85	  out.push(...creditNoteLines(invoice, notes));
86	  if (settlements.length > 0) out.push('', ...settlementLines(invoice, settlements));
87	  out.push('', `Balance due: ${formatAmount(invoiceBalance(invoice, notes, settlements), currency)}`);
88	  return `${out.join('\n')}\n`;
89	}
