1	/**
2	 * The text of the messages customers get: renewal reminders, change
3	 * confirmations, payment reminders and credit note notices. Delivery happens
4	 * elsewhere. These only produce a subject and a body.
5	 */
6	
7	import { formatLongDate } from '../core/dates.mjs';
8	import { formatAmount } from '../core/money.mjs';
9	
10	function message(subject, paragraphs) {
11	  return { subject, body: `${paragraphs.join('\n\n')}\n` };
12	}
13	
14	function greeting(customer) {
15	  return customer ? `Hello ${customer.name},` : 'Hello,';
16	}
17	
18	export function renewalReminder({ customer, renewsOn, amount, currency, planName }) {
19	  return message(`Your ${planName} plan renews on ${formatLongDate(renewsOn)}`, [
20	    greeting(customer),
21	    `Your ${planName} plan renews on ${formatLongDate(renewsOn)}. ` +
22	      `We will invoice ${formatAmount(amount, currency)}, before any account credit you hold.`,
23	    'If you want to change your plan, you can do that any time before the renewal date.',
24	  ]);
25	}
26	
27	export function changeConfirmation({ customer, invoice }) {
28	  const { currency, total, amountDue, creditApplied } = invoice;
29	  const paragraphs = [greeting(customer), `Your plan change is confirmed on invoice ${invoice.number}.`];
30	  if (total < 0) {
31	    paragraphs.push(`This leaves ${formatAmount(-total, currency)} of credit on your account.`);
32	  } else {
33	    paragraphs.push(`The change comes to ${formatAmount(total, currency)}.`);
34	    if (creditApplied > 0) {
35	      paragraphs.push(`We used ${formatAmount(creditApplied, currency)} of your account credit towards it.`);
36	    }
37	    paragraphs.push(`The amount to pay is ${formatAmount(amountDue, currency)}.`);
38	  }
39	  return message(`Your plan change, invoice ${invoice.number}`, paragraphs);
40	}
41	
42	export function paymentReminder({ customer, invoice, balance, stage }) {
43	  const { currency, number } = invoice;
44	  const subjects = {
45	    overdue: `Invoice ${number} is overdue`,
46	    'first-reminder': `Reminder: invoice ${number} is unpaid`,
47	    'second-reminder': `Second reminder: invoice ${number} is unpaid`,
48	    'final-notice': `Final notice for invoice ${number}`,
49	  };
50	  if (!subjects[stage]) throw new RangeError(`Unknown reminder stage: ${stage}`);
51	  return message(subjects[stage], [
52	    greeting(customer),
53	    `We have not received full payment for invoice ${number}, ` +
54	      `issued on ${formatLongDate(invoice.issueDate)}. ` +
55	      `The open balance is ${formatAmount(balance, currency)}.`,
56	    'If you have already paid, please ignore this message.',
57	  ]);
58	}
59	
60	export function creditNoteNotice({ customer, note }) {
61	  const { currency, settlement } = note;
62	  const paragraphs = [
63	    greeting(customer),
64	    `We have issued credit note ${note.number} for ${formatAmount(note.total, currency)} ` +
65	      `against invoice ${note.invoiceNumber}.`,
66	  ];
67	  if (note.reason) paragraphs.push(`Reason: ${note.reason}.`);
68	  if (settlement) {
69	    const { againstBalance, refunded, toAccount } = settlement;
70	    if (againstBalance > 0) {
71	      paragraphs.push(`${formatAmount(againstBalance, currency)} reduces what you owe on the invoice.`);
72	    }
73	    if (refunded > 0) {
74	      paragraphs.push(`${formatAmount(refunded, currency)} will be refunded to you.`);
75	    }
76	    if (toAccount > 0) {
77	      paragraphs.push(`${formatAmount(toAccount, currency)} goes back onto your account as credit.`);
78	    }
79	  }
80	  return message(`Credit note ${note.number}`, paragraphs);
81	}
82	
83	export function welcomeNotice({ customer, planName, invoice }) {
84	  const { currency, number, amountDue, issueDate } = invoice;
85	  return message(`Welcome to ${planName}`, [
86	    greeting(customer),
87	    `Your ${planName} subscription started on ${formatLongDate(issueDate)}.`,
88	    `Your first invoice is ${number}, with ${formatAmount(amountDue, currency)} to pay.`,
89	  ]);
