91	
92	export function cancellationNotice({ customer, planName, endsOn, invoice = null }) {
93	  const paragraphs = [
94	    greeting(customer),
95	    `Your ${planName} subscription ends on ${formatLongDate(endsOn)}.`,
96	  ];
97	  if (invoice && invoice.total < 0) {
98	    const credit = formatAmount(-invoice.total, invoice.currency);
99	    paragraphs.push(`${credit} for the time you will not use is now on your account.`);
