26	/** The tax region a tax number belongs to, or null if it is not one we know. */
27	export function taxNumberRegion(taxNumber) {
28	  const region = String(taxNumber).slice(0, 2);
29	  const format = TAX_NUMBER_FORMATS[region];
30	  return format && format.test(taxNumber) ? region : null;
31	}
32	
33	function normalizeAddress(address) {
34	  if (!address) return null;
35	  const { line1, line2 = '', city, postalCode = '', country } = address;
36	  assertText(line1, 'Address line 1');
37	  assertText(city, 'City');
38	  assertText(country, 'Country');
39	  return Object.freeze({ line1, line2, city, postalCode, country });
40	}
41	
42	function normalizeCustomer(input) {
43	  const { id, name, email = null, address = null, taxNumber = null, taxNumberCheckedOn = null } = input;
44	  assertText(id, 'Customer id');
45	  assertText(name, 'Customer name');
46	  if (email !== null && !EMAIL.test(email)) throw new RangeError(`Not an email address: ${email}`);
47	  if (taxNumber !== null && taxNumberRegion(taxNumber) === null) {
48	    throw new RangeError(`Not a tax number we recognise: ${taxNumber}`);
49	  }
50	  if (taxNumberCheckedOn !== null) parseIsoDate(taxNumberCheckedOn);
51	  return Object.freeze({
52	    id,
53	    name,
54	    email,
55	    address: normalizeAddress(address),
56	    taxNumber,
57	    taxNumberCheckedOn,
58	  });
59	}
