61	/**
62	 * Whether invoices to this customer in `region` go out with no tax: they hold a
63	 * checked tax number from that region, and it is not the seller's own.
64	 */
65	export function isReverseCharge(customer, region, sellerRegion) {
66	  if (!customer || !customer.taxNumber || !customer.taxNumberCheckedOn) return false;
67	  if (!sellerRegion || region === sellerRegion) return false;
68	  return taxNumberRegion(customer.taxNumber) === region;
69	}
