71	/** The address block for documents, as lines of text. */
72	export function addressLines(customer) {
73	  const lines = [customer.name];
74	  const { address } = customer;
75	  if (address) {
76	    lines.push(address.line1);
77	    if (address.line2) lines.push(address.line2);
78	    lines.push(`${address.postalCode} ${address.city}`.trim(), address.country);
79	  }
80	  if (customer.taxNumber) lines.push(`Tax number ${customer.taxNumber}`);
81	  return lines;
82	}
