84	export function createCustomerRegistry() {
85	  const customers = new Map();
86	  return {
87	    add(input) {
88	      const customer = normalizeCustomer(input);
89	      if (customers.has(customer.id)) throw new RangeError(`Customer ${customer.id} already exists`);
90	      customers.set(customer.id, customer);
91	      return customer;
92	    },
93	    update(id, changes) {
94	      const current = customers.get(id);
95	      if (!current) throw new UnknownRecordError('customer', id);
96	      const customer = normalizeCustomer({ ...current, ...changes, id });
97	      customers.set(id, customer);
98	      return customer;
99	    },
100	    find: (id) => customers.get(id) ?? null,
101	    get(id) {
102	      const customer = customers.get(id);
103	      if (!customer) throw new UnknownRecordError('customer', id);
104	      return customer;
105	    },
106	    all: () => [...customers.values()],
107	  };
108	}
109	
110	/** The block of text at the top of a document sent to a customer. */
111	export function documentHeader(customer, documentNumber) {
112	  return [...addressLines(customer), '', `Document ${documentNumber}`].join('\n');
113	}
