  assert.throws(() => book.changePlan('sub_1', { date: '2024-05-01', seats: 2 }), RangeError);
  assert.throws(() => book.changePlan('sub_1', { date: '2024-03-31', seats: 2 }), RangeError);
  assert.throws(() => book.changePlan('sub_1', { date: '2024-04-10', seats: 0 }), RangeError);
  assert.throws(() => book.changePlan('sub_9', { date: '2024-04-10', seats: 2 }), RangeError);
});

test('previewing a change changes nothing', () => {
  const book = makeBook();
  subscribeTo(book);
  const preview = book.previewChange('sub_1', { date: '2024-04-10', planCode: 'business' });
  assert.equal(preview.number, 'PREVIEW');
  assert.equal(book.subscription('sub_1').plan.code, 'team');
  assert.equal(book.invoices().length, 1);
  const real = book.changePlan('sub_1', { date: '2024-04-10', planCode: 'business' });
  assert.equal(real.total, preview.total);
});

test('a scheduled change takes effect at the renewal', () => {
  const book = makeBook();
  subscribeTo(book, { seats: 3 });
  book.scheduleForRenewal('sub_1', { seats: 1 });
  assert.equal(book.subscription('sub_1').seats, 3);
  const invoice = book.renew('sub_1');
  assert.equal(invoice.subtotal, 3000);
  assert.equal(book.subscription('sub_1').seats, 1);
  assert.equal(book.subscription('sub_1').scheduled, null);
});

test('a scheduled change can be cleared', () => {
  const book = makeBook();
  subscribeTo(book, { seats: 3 });
  book.scheduleForRenewal('sub_1', { planCode: 'business' });
  book.clearSchedule('sub_1');
  assert.equal(book.renew('sub_1').subtotal, 9000);
});

test('cancelling at period end stops the next renewal', () => {
  const book = makeBook();
  subscribeTo(book);
  assert.equal(book.cancel('sub_1', { date: '2024-04-10', mode: 'period-end' }), null);
  assert.equal(book.subscription('sub_1').status, 'active');
  assert.equal(book.renew('sub_1'), null);
  assert.equal(book.subscription('sub_1').status, 'ended');
  assert.equal(book.subscription('sub_1').endedOn, '2024-05-01');
  assert.throws(() => book.renew('sub_1'), RangeError);
});

test('cancelling straight away gives credit for the unused time', () => {
  const book = makeBook();
  subscribeTo(book);
  const invoice = book.cancel('sub_1', { date: '2024-04-10' });
  assert.ok(invoice.total < 0);
  assert.equal(invoice.amountDue, 0);
  assert.equal(book.accountCredit('cus_1', 'USD'), -invoice.total);
  assert.equal(book.subscription('sub_1').status, 'ended');
  assert.throws(() => book.changePlan('sub_1', { date: '2024-04-11', seats: 2 }), RangeError);
});

test('payments reduce the balance and cannot exceed it', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  book.pay(invoice.number, { amount: 1000, date: '2024-04-02' });
  assert.equal(book.balanceOf(invoice.number), invoice.total - 1000);
  assert.throws(() => book.pay(invoice.number, { amount: invoice.total, date: '2024-04-03' }), RangeError);
  assert.throws(() => book.pay(invoice.number, { amount: 0, date: '2024-04-03' }), RangeError);
  assert.throws(() => book.pay(invoice.number, { amount: 1, date: '2024-03-01' }), RangeError);
  book.pay(invoice.number, { amount: invoice.total - 1000, date: '2024-04-03' });
  assert.equal(book.balanceOf(invoice.number), 0);
});

test('a write-off closes a balance without cash', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  book.writeOff(invoice.number, { amount: invoice.total, date: '2024-09-01' });
  assert.equal(book.balanceOf(invoice.number), 0);
  assert.equal(book.customerSummary('cus_1', 'USD').writtenOff, invoice.total);
  assert.equal(book.customerSummary('cus_1', 'USD').received, 0);
});

test('a credit note on an unpaid invoice reduces what is owed', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  const note = book.creditInvoice(invoice.number, {
    date: '2024-04-05',
    lines: [{ lineIndex: 0, amount: 1000 }],
  });
  assert.equal(note.number, 'CN-0001');
  assert.equal(note.total, 1200);
  assert.deepEqual(note.settlement, { againstBalance: 1200, refunded: 0, toAccount: 0 });
  assert.equal(book.balanceOf(invoice.number), invoice.total - 1200);
});

test('a credit note on a paid invoice is refunded', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  book.pay(invoice.number, { amount: invoice.total, date: '2024-04-02' });
  const note = book.creditInvoice(invoice.number, { date: '2024-04-05' });
  assert.deepEqual(note.settlement, { againstBalance: 0, refunded: invoice.total, toAccount: 0 });
  assert.equal(book.balanceOf(invoice.number), 0);
  assert.deepEqual(
    book.refundsToPay().map(({ noteNumber, amount }) => [noteNumber, amount]),
    [[note.number, invoice.total]],
  );
  book.markRefundPaid(note.number);
  assert.deepEqual(book.refundsToPay(), []);
});

test('the timeline records what happened', () => {
  const book = makeBook();
  subscribeTo(book);
  book.changePlan('sub_1', { date: '2024-04-10', seats: 2 });
  book.renew('sub_1');
  assert.deepEqual(book.timeline('sub_1'), [
    '2024-04-01 subscribed (INV-0001)',
    '2024-04-10 changed (INV-0002)',
    '2024-05-01 renewed (INV-0003)',
  ]);
});

test('unknown records are reported', () => {
  const book = makeBook();
  assert.throws(() => book.invoice('INV-9'), RangeError);
  assert.throws(() => book.subscription('sub_9'), RangeError);
  assert.throws(() => book.creditInvoice('INV-9', { date: '2024-01-01' }), RangeError);
});

test('reverse charge customers are billed without tax', () => {
  const book = makeBook({ sellerRegion: 'BE' });
  book.customers.add({
    id: 'cus_1',
    name: 'Example BV',
    taxNumber: 'NL123456789B01',
    taxNumberCheckedOn: '2024-01-01',
  });
  assert.equal(subscribeTo(book).taxTotal, 0);
});
import assert from 'node:assert/strict';
import test from 'node:test';

import {
  allocate,
  amountDueBy,
  buildInvoice,
  defineTaxTable,
  instalmentStatus,
  planInstalments,
  rateOn,
  sumAmounts,
  taxForAmount,
} from '../src/index.mjs';

const base = { number: 'INV-1', customerId: 'cus_1', currency: 'USD', issueDate: '2024-03-01' };

test('exact splits stay exact', () => {
  assert.deepEqual(allocate(1000, [1, 1, 2]), [250, 250, 500]);
  assert.deepEqual(allocate(0, [1, 2]), [0, 0]);
});

test('a single line takes everything', () => {
  assert.deepEqual(allocate(1234, [7]), [1234]);
});

test('parts add up to the amount', () => {
  assert.equal(sumAmounts(allocate(1000, [3, 7, 11, 13])), 1000);
});

test('an even three-way split gives the spare unit to the first line', () => {
  assert.deepEqual(allocate(10000, [1, 1, 1]), [3334, 3333, 3333]);
});

test('weights must include a positive one', () => {
  assert.throws(() => allocate(100, [0, 0]), RangeError);
  assert.throws(() => allocate(100, []), RangeError);
  assert.throws(() => allocate(100, [-1, 2]), RangeError);
});

test('a single line is taxed and totalled', () => {
  const invoice = buildInvoice({
    ...base,
    lines: [{ description: 'Team plan', unitAmount: 2900, quantity: 2, taxRateBps: 2100 }],
  });
  assert.equal(invoice.subtotal, 5800);
  assert.equal(invoice.netTotal, 5800);
  assert.equal(invoice.taxTotal, 1218);
  assert.equal(invoice.total, 7018);
  assert.equal(invoice.amountDue, 7018);
  assert.equal(invoice.lines[0].tax, 1218);
  assert.equal(invoice.lines[0].gross, 7018);
});

test('tax rounds half-even', () => {
  assert.equal(taxForAmount(5, 1000), 0);
  assert.equal(taxForAmount(15, 1000), 2);
  assert.equal(taxForAmount(25, 1000), 2);
});

test('a percentage discount comes off before tax', () => {
  const invoice = buildInvoice({
    ...base,
    discount: { percentBps: 1000 },
    lines: [{ description: 'Team plan', unitAmount: 10000, taxRateBps: 2100 }],
  });
  assert.equal(invoice.discountTotal, 1000);
  assert.equal(invoice.netTotal, 9000);
  assert.equal(invoice.taxTotal, 1890);
  assert.equal(invoice.total, 10890);
});

test('a discount needs one form and has to fit', () => {
  const lines = [{ description: 'Team plan', unitAmount: 1000 }];
  assert.throws(() => buildInvoice({ ...base, discount: { fixed: 2000 }, lines }), RangeError);
  assert.throws(() => buildInvoice({ ...base, discount: {}, lines }), TypeError);
  assert.throws(
    () => buildInvoice({ ...base, discount: { fixed: 1, percentBps: 1 }, lines }),
    TypeError,
  );
});

test('an invoice needs lines, a number and a real date', () => {
  const lines = [{ description: 'Team plan', unitAmount: 1000 }];
  assert.throws(() => buildInvoice({ ...base, lines: [] }), RangeError);
  assert.throws(() => buildInvoice({ ...base, number: '', lines }), TypeError);
  assert.throws(() => buildInvoice({ ...base, issueDate: '2024-02-30', lines }), RangeError);
  assert.throws(() => buildInvoice({ ...base, currency: 'XXX', lines }), RangeError);
});

test('the tax summary has one row per rate', () => {
  const invoice = buildInvoice({
    ...base,
    lines: [
      { description: 'Plan', unitAmount: 10000, taxRateBps: 2100 },
      { description: 'Books', unitAmount: 2000, taxRateBps: 900 },
      { description: 'Add-on', unitAmount: 5000, taxRateBps: 2100 },
    ],
  });
  assert.deepEqual(invoice.taxSummary, [
    { rateBps: 2100, taxable: 15000, tax: 3150 },
    { rateBps: 900, taxable: 2000, tax: 180 },
  ]);
  assert.equal(invoice.taxTotal, 3330);
});

test('line items add up to the invoice total', () => {
  const invoice = buildInvoice({
    ...base,
    lines: [
      { description: 'Seat A', unitAmount: 1005, taxRateBps: 1000 },
      { description: 'Seat B', unitAmount: 1005, taxRateBps: 1000 },
      { description: 'Seat C', unitAmount: 1005, taxRateBps: 1000 },
    ],
  });
  assert.equal(sumAmounts(invoice.lines.map((line) => line.gross)), invoice.total);
});

test('a tax table gives the rate in force on a date', () => {
  const table = defineTaxTable({
    SE: [
      { from: '2025-07-01', rateBps: 2200 },
      { from: '2000-01-01', rateBps: 2500 },
    ],
  });
  assert.equal(rateOn(table, 'SE', '2025-06-30'), 2500);
  assert.equal(rateOn(table, 'SE', '2025-07-01'), 2200);
  assert.throws(() => rateOn(table, 'SE', '1999-12-31'), RangeError);
  assert.throws(() => rateOn(table, 'NO', '2025-01-01'), RangeError);
});

test('instalments spread a balance over monthly dates', () => {
  const plan = planInstalments(9000, 3, '2024-01-15');
  assert.deepEqual(plan, [
    { number: 1, due: '2024-01-15', amount: 3000 },
    { number: 2, due: '2024-02-15', amount: 3000 },
    { number: 3, due: '2024-03-15', amount: 3000 },
  ]);
  assert.equal(amountDueBy(plan, '2024-02-20'), 6000);
  assert.throws(() => planInstalments(0, 3, '2024-01-15'), RangeError);
});

test('payments cover instalments oldest first', () => {
  const plan = planInstalments(9000, 3, '2024-01-15');
  const status = instalmentStatus(plan, 4000, '2024-02-20');
  assert.deepEqual(
    status.map(({ state, open }) => [state, open]),
    [
      ['paid', 0],
      ['late', 2000],
      ['upcoming', 3000],
    ],
  );
});
import assert from 'node:assert/strict';
import test from 'node:test';

import {
  buildInvoice,
  creditInvoiceInFull,
  creditedToDate,
  invoiceBalance,
  issueCreditNote,
} from '../src/index.mjs';

const plainInvoice = () =>
  buildInvoice({
    number: 'INV-7',
    customerId: 'cus_1',
    currency: 'USD',
    issueDate: '2024-03-01',
    lines: [{ description: 'Team plan', unitAmount: 10000, taxRateBps: 2100 }],
  });

const discountedInvoice = () =>
  buildInvoice({
    number: 'INV-8',
    customerId: 'cus_1',
    currency: 'USD',
    issueDate: '2024-03-01',
    discount: { percentBps: 1000 },
    lines: [
      { description: 'Team plan', unitAmount: 1005, taxRateBps: 1000 },
      { description: 'Add-on', unitAmount: 2005, taxRateBps: 1000 },
      { description: 'Support', unitAmount: 3005, taxRateBps: 1000 },
    ],
  });

test('a partial credit note reverses net and tax', () => {
  const invoice = plainInvoice();
  const note = issueCreditNote(invoice, {
    number: 'CN-1',
    date: '2024-03-05',
    lines: [{ lineIndex: 0, amount: 2500 }],
  });
  assert.equal(note.netTotal, 2500);
  assert.equal(note.taxTotal, 525);
  assert.equal(note.total, 3025);
  assert.equal(invoiceBalance(invoice, [note]), invoice.total - 3025);
  assert.deepEqual(creditedToDate(invoice, [note]), [{ net: 2500, tax: 525 }]);
});

test('credit amounts can be given as decimal text', () => {
  const note = issueCreditNote(plainInvoice(), {
    number: 'CN-1',
    date: '2024-03-05',
    lines: [{ lineIndex: 0, amountText: '12.50' }],
  });
  assert.equal(note.netTotal, 1250);
});

test('a credit note cannot predate its invoice or name a missing line', () => {
  const invoice = plainInvoice();
  assert.throws(
    () =>
      issueCreditNote(invoice, {
        number: 'CN-1',
        date: '2024-02-01',
        lines: [{ lineIndex: 0, amount: 1 }],
      }),
    RangeError,
  );
  assert.throws(
    () =>
      issueCreditNote(invoice, {
        number: 'CN-1',
        date: '2024-03-05',
        lines: [{ lineIndex: 4, amount: 1 }],
      }),
    RangeError,
  );
});

test('notes from another invoice are refused', () => {
  const invoice = plainInvoice();
  const other = issueCreditNote(discountedInvoice(), {
    number: 'CN-1',
    date: '2024-03-05',
    lines: [{ lineIndex: 0, amount: 1 }],
  });
  assert.throws(() => creditedToDate(invoice, [other]), RangeError);
});

test('a plain invoice credited in full owes nothing', () => {
  const invoice = plainInvoice();
  const note = creditInvoiceInFull(invoice, { number: 'CN-1', date: '2024-03-05' });
  assert.equal(note.total, invoice.total);
  assert.equal(invoiceBalance(invoice, [note]), 0);
});

test('a discounted invoice credited in full owes nothing', () => {
  const invoice = discountedInvoice();
  const note = creditInvoiceInFull(invoice, { number: 'CN-1', date: '2024-03-05' });
  assert.equal(note.total, invoice.total);
  assert.equal(invoiceBalance(invoice, [note]), 0);
});

