/**
 * Spreads a rate group's tax over its lines. Each line gets its exact tax rounded
 * down or up (so within one unit of it, whatever its sign), the spare units going
 * to the lines with the biggest fractions, and the parts add up to `groupTax`.
 */
function spreadTax(members, rateBps, groupTax) {
  const shares = members.map(({ line }) => {
    const exact = BigInt(line.net) * BigInt(rateBps);
    let whole = exact / BASIS_POINTS_BIG;
    let fraction = exact % BASIS_POINTS_BIG;
    if (fraction < 0n) {
      whole -= 1n;
      fraction += BASIS_POINTS_BIG;
    }
    return { tax: whole, fraction };
  });
  let spare = BigInt(groupTax) - shares.reduce((sum, { tax }) => sum + tax, 0n);
  const byFraction = shares
    .map((share, index) => ({ ...share, index }))
    .sort((a, b) => (a.fraction === b.fraction ? a.index - b.index : a.fraction < b.fraction ? 1 : -1));
  for (const { index } of byFraction) {
    if (spare <= 0n) break;
    shares[index].tax += 1n;
    spare -= 1n;
  }
  return shares.map(({ tax }) => Number(tax));
}

const BASIS_POINTS_BIG = 10_000n;

/**
 * Adds `tax` and `gross` to each discounted line. The tax due is worked out per
 * rate on the group's net amount, and the lines show how it is spread.
 */
export function applyTax(lines) {
  const taxed = new Array(lines.length);
  for (const [rateBps, members] of groupByRate(lines)) {
    const groupTax = taxForAmount(taxableAmount(members), rateBps);
    const spread = spreadTax(members, rateBps, groupTax);
    members.forEach(({ line, position }, at) => {
      taxed[position] = { ...line, tax: spread[at], gross: line.net + spread[at] };
    });
  }
  return taxed;
}

