 * of a date. Only lines with a service period count, and only invoices issued by
 * then. What credit notes issued by then gave back on a line is no longer owed as
 * service. A line whose period is over has nothing left to defer, and one that has
 * not started defers all of it.
 */
export function deferredRevenue({ invoices, notes = [], currency, asOf }) {
  parseIsoDate(asOf);
  let total = 0;
  for (const invoice of invoices) {
    if (invoice.currency !== currency || compareDates(invoice.issueDate, asOf) > 0) continue;
    const credited = invoice.lines.map(() => 0);
    for (const note of notes) {
      if (note.invoiceNumber !== invoice.number || compareDates(note.date, asOf) > 0) continue;
      for (const { lineIndex, net } of note.lines) credited[lineIndex] += net;
    }
    invoice.lines.forEach((line, position) => {
      if (!line.period || line.net === 0) return;
      total += deferredPart(line, line.net - credited[position], asOf);
    });
  }
  return total;
}

function deferredPart(line, net, asOf) {
  const { start, end } = line.period;
  if (compareDates(asOf, end) >= 0) return 0;
  if (compareDates(asOf, start) < 0) return net;
  return scaleRounded(net, daysBetween(asOf, end), daysBetween(start, end));
}

