import assert from 'node:assert/strict';
import test from 'node:test';

import {
  allocate,
  buildInvoice,
  createBook,
  createCatalog,
  creditInvoiceInFull,
  defineCoupon,
  definePlan,
  defineTaxTable,
  formatAmount,
  invoiceBalance,
  issueCreditNote,
  parseAmount,
  periodAt,
  planChangeAmounts,
  prorationFraction,
  renewalsAfter,
  sumAmounts,
} from '../src/index.mjs';
import { makeBook, subscribeTo } from './support/world.mjs';

/** A small deterministic generator, so failures can be reproduced. */
function lcg(seed) {
  let state = seed;
  return (max) => {
    state = (state * 1_103_515_245 + 12_345) % 2_147_483_648;
    return state % max;
  };
}

test('a month-end anchor keeps its billing day after a short month', () => {
  assert.deepEqual(
    [0, 1, 2, 3].map((index) => periodAt('2023-01-31', 1, index).end),
    ['2023-02-28', '2023-03-31', '2023-04-30', '2023-05-31'],
  );
  assert.equal(periodAt('2023-01-31', 1, 13).start, '2024-02-29');
  assert.equal(periodAt('2024-02-29', 12, 1).start, '2025-02-28');
  assert.equal(periodAt('2024-02-29', 12, 4).start, '2028-02-29');
  assert.deepEqual(renewalsAfter('2023-01-31', 1, '2023-03-01', 2), ['2023-03-31', '2023-04-30']);
});

test('the day of a change is billed at the new price', () => {
  const period = { start: '2024-02-01', end: '2024-03-01' };
  assert.deepEqual(prorationFraction(period, '2024-02-16'), { remaining: 14, total: 29 });
  assert.deepEqual(prorationFraction(period, '2024-02-01'), { remaining: 29, total: 29 });
  assert.deepEqual(
    planChangeAmounts({ oldAmount: 2900, newAmount: 5800, period, changeDate: '2024-02-16' }),
    { credit: -1400, charge: 2800, net: 1400 },
  );
});

