test('allocation is exact, fair and mirrors for negative amounts', () => {
  const next = lcg(7);
  for (let round = 0; round < 500; round += 1) {
    const weights = Array.from({ length: 1 + next(6) }, () => (next(4) === 0 ? 0 : next(5000)));
    if (weights.every((weight) => weight === 0)) continue;
    const amount = next(2_000_001) - 1_000_000;
    const parts = allocate(amount, weights);
    assert.equal(sumAmounts(parts), amount);
    const total = sumAmounts(weights);
    parts.forEach((part, position) => {
      assert.ok(Math.abs(part - (amount * weights[position]) / total) < 1);
      if (weights[position] === 0) assert.equal(part, 0);
    });
    assert.deepEqual(allocate(-amount, weights), parts.map((part) => (part === 0 ? 0 : -part)));
  }
  assert.deepEqual(allocate(5, [1, 0]), [5, 0]);
  assert.deepEqual(allocate(-1, [1, 1]), [-1, 0]);
});

test('line tax adds up to the tax due and stays near each line exact tax', () => {
  const next = lcg(11);
  for (let round = 0; round < 300; round += 1) {
    const lines = Array.from({ length: 1 + next(5) }, (_, position) => ({
      description: `Line ${position}`,
      unitAmount: next(3) === 0 ? -(1 + next(9999)) : next(20000),
      taxRateBps: [0, 700, 2100][next(3)],
    }));
    if (lines.every((line) => line.unitAmount <= 0)) lines.push({ description: 'Base', unitAmount: 5000 });
    const invoice = buildInvoice({
      number: 'INV-1',
      customerId: 'c',
      currency: 'USD',
      issueDate: '2024-01-01',
      discount: next(2) === 0 ? { percentBps: 1 + next(5000) } : null,
      lines,
    });
    assert.equal(sumAmounts(invoice.lines.map((line) => line.tax)), invoice.taxTotal);
    assert.equal(sumAmounts(invoice.lines.map((line) => line.gross)), invoice.total);
    assert.equal(sumAmounts(invoice.lines.map((line) => line.net)), invoice.netTotal);
    for (const line of invoice.lines) {
      assert.ok(Math.abs(line.tax - (line.net * line.taxRateBps) / 10_000) < 1);
    }
  }
});

