  subscribeTo(book, { seats: 3 });
  book.scheduleForRenewal('sub_1', { seats: 1 });
  book.changePlan('sub_1', { date: '2024-04-10', planCode: 'business' });
  assert.deepEqual(book.subscription('sub_1').scheduled, { seats: 1 });
  assert.equal(book.renew('sub_1').subtotal, 6000);
});

test('unused time goes back at the rate it was charged at', () => {
  const taxTable = defineTaxTable({
    NL: [
      { from: '2000-01-01', rateBps: 2000 },
      { from: '2024-04-10', rateBps: 2100 },
    ],
  });
  const book = makeBook({ taxTable });
  subscribeTo(book);
  const change = book.changePlan('sub_1', { date: '2024-04-10', planCode: 'business' });
  assert.deepEqual(change.lines.map((line) => line.taxRateBps), [2000, 2100]);
  assert.equal(change.taxSummary.length, 2);
});

test('a failed operation does not use up a document number', () => {
  const book = makeBook();
  subscribeTo(book);
  assert.throws(() => book.changePlan('sub_1', { date: '2024-06-01', seats: 2 }), RangeError);
  assert.throws(() => book.creditInvoice('INV-0001', { date: '2024-04-02', lines: [{ lineIndex: 0, amount: 99999 }] }));
  assert.equal(book.renew('sub_1').number, 'INV-0002');
  assert.equal(book.creditInvoice('INV-0001', { date: '2024-04-02' }).number, 'CN-0001');
});

test('credit notes after a plan change cannot refund the time already given back', () => {
  const book = makeBook();
  subscribeTo(book, { region: null });
  book.changePlan('sub_1', { date: '2024-04-16', planCode: 'business' });
  const origin = book.invoice('INV-0001');
  const left = book.remainingCreditable('INV-0001')[0];
  assert.ok(left < origin.lines[0].net);
  assert.throws(() =>
    book.creditInvoice('INV-0001', { date: '2024-04-20', lines: [{ lineIndex: 0, amount: left + 1 }] }),
  );
});

test('reports keep currencies apart', () => {
  const book = makeBook();
  const usd = subscribeTo(book);
  const eur = subscribeTo(book, { id: 'sub_2', customerId: 'cus_2', currency: 'EUR' });
  book.creditInvoice(eur.number, { date: '2024-04-02' });
  assert.deepEqual(book.revenueByMonth('USD'), [{ month: '2024-04', amount: 3000 }]);
  assert.deepEqual(book.taxReport('USD', '2024-04'), [{ rateBps: 2000, taxable: 3000, tax: 600 }]);
  assert.equal(usd.currency, 'USD');
});

test('deferred revenue drops when a credit note gives a charge back', () => {
  const book = makeBook();
  const invoice = subscribeTo(book);
  book.creditInvoice(invoice.number, { date: '2024-04-02', lines: [{ lineIndex: 0, amount: 1500 }] });
  assert.equal(book.deferredRevenue('USD', '2024-04-01'), 3000);
  assert.equal(book.deferredRevenue('USD', '2024-04-02'), 1500 - Math.round((1500 * 1) / 30));
});
